package com.thralloverhead;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("thrallTimer")
public interface ThrallOverheadConfig extends Config
{
    @ConfigItem(
        keyName = "showBar",
        name = "Bar",
        description = "Display the bar above summoned thralls",
        position = 0
    )
    default boolean showBar()
    {
        return true;
    }

    @Range(min = 20, max = 100)
    @ConfigItem(
        keyName = "barWidth",
        name = "Bar Width",
        description = "Width of the thrall timer bar (20-100)",
        position = 1
    )
    default int barWidth()
    {
        return 40;
    }

    @Range(min = 2, max = 15)
    @ConfigItem(
        keyName = "barHeight",
        name = "Bar Height",
        description = "Height of the thrall timer bar (2-15)",
        position = 2
    )
    default int barHeight()
    {
        return 5;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(
        keyName = "barOffset",
        name = "Bar Vertical Offset",
        description = "Adjust the vertical position of the bar (0-100)",
        position = 3
    )
    default int barOffset()
    {
        return 35;
    }

    @ConfigItem(
        keyName = "showBorder",
        name = "Border",
        description = "Display a border around the thrall timer bar",
        position = 4
    )
	default boolean showBorder()
	{
		return false;
	}

    @ConfigItem(
        keyName = "borderColor",
        name = "Border color",
        description = "Border color of duration bar",
        position = 5
    )
    default Color borderColor()
    {
        return Color.WHITE;
    }

    @ConfigItem(
        keyName = "fillColor",
        name = "Fill color",
        description = "Border fill color of duration bar",
        position = 5
    )
    default Color fillColor()
    {
        return Color.BLACK;
    }

    @ConfigItem(
        keyName = "mageColor",
        name = "Mage (Ghost)",
        description = "Bar color for mage thrall",
        position = 6
    )
    default Color mageColor()
    {
        return new Color(32, 181, 191);
    }

    @ConfigItem(
        keyName = "rangeColor",
        name = "Range (Skeleton)",
        description = "Bar color for range thrall",
        position = 7
    )
    default Color rangeColor()
    {
        return new Color(200, 220, 88);
    }

    @ConfigItem(
        keyName = "meleeColor",
        name = "Melee (Zombie)",
        description = "Bar color for melee thralls",
        position = 8
    )
    default Color meleeColor()
    {
        return new Color(180, 40, 40);
    }

    @ConfigItem(
        keyName = "flashWarning",
        name = "Flash Warning",
        description = "Flash the background when a thrall is about to expire",
        position = 9
    )
    default boolean flashWarning()
    {
        return true;
    }

    @ConfigItem(
        keyName = "flashWarningThrall",
        name = "Flash thrall outline",
        description = "Flash the outline of the thrall when it's about to expire",
        position = 10
    )
    default boolean flashWarningThrall()
    {
        return false;
    }

    @Range(min = 1, max = 30)
    @ConfigItem(
        keyName = "warningThreshold",
        name = "Warning Threshold",
        description = "Number of ticks remaining before the warning starts (1-30)",
        position = 11
    )
    default int warningThreshold()
    {
        return 10;
    }

    @ConfigItem(
        keyName = "showTimer",
        name = "Show a timer (seconds)",
        description = "Display remaining time in seconds beside the bar or above the thrall",
        position = 12
    )
    default boolean showTimer()
    {
        return false;
    }
}

package com.thralloverhead;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class ThrallOverheadOverlay extends Overlay
{
    private final ThrallOverheadConfig config;

    private static final Color WARNING_COLOR = Color.RED;
    private static final long FLASH_INTERVAL_MS = 200;

    @Getter
    @Setter
    private NPC thrall;

    @Setter
    private ThrallTimer thrallTimer;

    @Inject
    public ThrallOverheadOverlay(ThrallOverheadConfig config)
    {
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if ((!config.showBar() && !config.showTimer() && !config.flashWarningThrall())
            || thrall == null || thrallTimer == null || thrallTimer.isExpired())
        {
            return null;
        }

        int barWidth = config.barWidth();
        int barHeight = config.barHeight();
        int barOffset = config.barOffset();

        Point canvasPoint = thrall.getCanvasTextLocation(
            graphics,
            "",
            thrall.getLogicalHeight() + barOffset
        );

        if (canvasPoint == null)
        {
            return null;
        }

        int x = canvasPoint.getX() - barWidth / 2;
        int y = canvasPoint.getY();

        // Flash the background red during the final few ticks
        boolean warning = (config.flashWarning() || config.flashWarningThrall())
            && thrallTimer.getTicksRemaining() <= config.warningThreshold();

        boolean flashRed = warning &&
            (System.currentTimeMillis() / FLASH_INTERVAL_MS) % 2 == 0;

        // Background
        if (config.showBar())
        {
            // Flash duration bar
            graphics.setColor(flashRed && config.flashWarning() ? WARNING_COLOR : config.fillColor());
            graphics.fillRect(x, y, barWidth, barHeight);

            // Remaining duration
            int progressWidth = (int) (barWidth * thrallTimer.getProgress());

            graphics.setColor(getThrallColor());
            graphics.fillRect(x, y, progressWidth, barHeight);

            // Border
            if (config.showBorder())
            {
                graphics.setColor(config.borderColor());
                graphics.drawRect(x, y, barWidth, barHeight);
            }
        }

        // Thrall flash
        if (config.flashWarningThrall() && flashRed)
        {
            OverlayUtil.renderPolygon(graphics, thrall.getConvexHull(), WARNING_COLOR);
        }

        // Optional Timer
        if (config.showTimer())
        {
            int secondsRemaining = (int) Math.ceil(thrallTimer.getSecondsRemaining());
            String timerText = (secondsRemaining - 1) + "";

            FontMetrics metrics = graphics.getFontMetrics();

            graphics.setColor(warning && config.flashWarning() && !flashRed
                ? WARNING_COLOR : Color.WHITE);

            graphics.drawString(
                timerText,
                config.showBar() ? x + barWidth + 4 : canvasPoint.getX() - metrics.stringWidth(timerText) / 2,
                config.showBar() ? y + (barHeight + metrics.getAscent() - metrics.getDescent()) / 2 : y - 6
            );
        }

        return null;
    }

    private Color getThrallColor()
    {
        int summonedThrall = thrall.getId();

        if (Thralls.GHOSTS.contains(summonedThrall))
        {
            return config.mageColor();
        }

        if (Thralls.SKELETONS.contains(summonedThrall))
        {
            return config.rangeColor();
        }

        if (Thralls.ZOMBIES.contains(summonedThrall))
        {
            return config.meleeColor();
        }

        return Color.GREEN;
    }
}

package com.thralloverhead;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
    name = "Thrall Overhead"
)
public class ThrallOverheadPlugin extends Plugin
{
    protected static final String RESURRECT_THRALL_MESSAGE_START = "You resurrect a ";
    protected static final String RESURRECT_THRALL_MESSAGE_END = " thrall.</col>";

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ThrallOverheadOverlay overlay;

    private ThrallTimer thrallTimer;

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        log.debug("Thrall Timer started!");
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);

        thrallTimer = null;
        overlay.setThrallTimer(null);
        overlay.setThrall(null);

        log.debug("Thrall Timer stopped!");
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        String message = event.getMessage();

        if (message.contains(RESURRECT_THRALL_MESSAGE_START)
            && message.endsWith(RESURRECT_THRALL_MESSAGE_END))
        {
            int duration = client.getBoostedSkillLevel(Skill.MAGIC);

            // Combat Achievement master tier doubles thrall duration.
            if (client.getVarbitValue(VarbitID.CA_TIER_STATUS_MASTER) == 2)
            {
                duration *= 2;
            }

            thrallTimer = new ThrallTimer(duration);
            overlay.setThrallTimer(thrallTimer);

        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (thrallTimer == null)
        {
            return;
        }

        thrallTimer.tick();

        if (thrallTimer.isExpired())
        {
            thrallTimer = null;
            overlay.setThrallTimer(null);
        }
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        NPC npc = event.getNpc();

        if (isThrall(npc))
        {
            overlay.setThrall(npc);
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        if (event.getNpc() == overlay.getThrall())
        {
            overlay.setThrall(null);
        }
    }

    private boolean isThrall(NPC npc)
    {
       return Thralls.ALL_THRALLS.contains(npc.getId());
    }

    @Provides
    ThrallOverheadConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ThrallOverheadConfig.class);
    }
}

package com.thralloverhead;

import lombok.Getter;

@Getter
public class ThrallTimer
{
    private final int duration;
    private int ticksRemaining;
    private final long startTime;
    private final long durationNanos;

    public ThrallTimer(int duration)
    {
        if (duration <= 0)
        {
            throw new IllegalArgumentException("Duration must be greater than zero");
        }

        this.duration = duration;
        this.ticksRemaining = duration;
        this.startTime = System.nanoTime();
        this.durationNanos = duration * 600_000_000L;
    }

    public void tick()
    {
        if (!isExpired())
        {
            ticksRemaining--;
        }
    }

    public double getSecondsRemaining()
    {
        long elapsed = System.nanoTime() - startTime;
        return Math.max(0, (durationNanos - elapsed) / 1_000_000_000.0);
    }

    public boolean isExpired()
    {
        return ticksRemaining <= 0;
    }

    public double getProgress()
    {
        return (double) ticksRemaining / duration;
    }
}

package com.thralloverhead;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import lombok.Getter;

@Getter
public enum Thralls
{
    LESSER_GHOST(10878),
    SUPERIOR_GHOST(10879),
    GREATER_GHOST(10880),
    LESSER_GHOST_IMP(15701),
    SUPERIOR_GHOST_IMP(15702),
    GREATER_GHOST_IMP(15703),

    LESSER_SKELETON(10881),
    SUPERIOR_SKELETON(10882),
    GREATER_SKELETON(10883),
    LESSER_SKELETON_IMP(15704),
    SUPERIOR_SKELETON_IMP(15705),
    GREATER_SKELETON_IMP(15706),

    LESSER_ZOMBIE(10884),
    SUPERIOR_ZOMBIE(10885),
    GREATER_ZOMBIE(10886),
    LESSER_ZOMBIE_IMP(15707),
    SUPERIOR_ZOMBIE_IMP(15708),
    GREATER_ZOMBIE_IMP(15709);

    private final int id;

    Thralls(int id)
    {
        this.id = id;
    }

    public static final List<Integer> ALL_THRALLS =
        Arrays.stream(values())
            .map(Thralls::getId)
            .collect(Collectors.toList());

    public static final List<Integer> GHOSTS = List.of(
        LESSER_GHOST.id, SUPERIOR_GHOST.id, GREATER_GHOST.id,
        LESSER_GHOST_IMP.id, SUPERIOR_GHOST_IMP.id, GREATER_GHOST_IMP.id
    );

    public static final List<Integer> SKELETONS = List.of(
        LESSER_SKELETON.id, SUPERIOR_SKELETON.id, GREATER_SKELETON.id,
        LESSER_SKELETON_IMP.id, SUPERIOR_SKELETON_IMP.id, GREATER_SKELETON_IMP.id
    );

    public static final List<Integer> ZOMBIES = List.of(
        LESSER_ZOMBIE.id, SUPERIOR_ZOMBIE.id, GREATER_ZOMBIE.id,
        LESSER_ZOMBIE_IMP.id, SUPERIOR_ZOMBIE_IMP.id, GREATER_ZOMBIE_IMP.id
    );
}

